import {sourceGroups,soundOriginLabel} from './sound-catalog.js';
import {SAMPLE_PRESETS,normalizeSampler,samplePreset,samplerInfo} from './sampler-core.js';
import {setTrackSampler,planSamplerPalette} from './sampler-edit.js';
import {sampleLibrary} from './sample-library.js';
const noteName=p=>['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][p%12]+(Math.floor(p/12)-1);
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createSamplerUI({getProject,getRevision,getSelected,commit,protectedChange,modal,toast,preview,isQuiet,library=sampleLibrary}){
 let serial=0;
 return function showSampler(trackId){
  const track=getProject().tracks.find(t=>t.id===trackId);if(!track)return toast('请先选择轨道');
  const choices=Object.entries(SAMPLE_PRESETS).filter(([,p])=>p.instrument===track.instrument);if(!choices.length)return toast('这个音源暂没有随包采样；仍可以使用合成音色。');
  const ticket=++serial,at=getRevision();let draft=track.sampler?{...track.sampler}:null,loading=false;
  modal('声音来源 · 采样乐器',`<div class="sampler-form"><p><strong>${escape(track.name)}</strong> · 只换此轨的发声方式，不生成或移动音符，不改其他共享实例的音色。</p><label class="modal-label" for="sampler-preset">声音来源<select id="sampler-preset"><option value="">内置合成 · 保留原来的音色参数</option>${sourceGroups(track.instrument).map(group=>`<optgroup label="${escape(group.name)}">${group.sounds.map(p=>`<option value="${p.id}" ${draft?.preset===p.id?'selected':''}>${escape(p.name)}</option>`).join('')}</optgroup>`).join('')}</select></label><div id="sampler-description" class="modal-notice"></div><div id="sampler-fields" class="phrase-fields" ${draft?'':'hidden'}><label>采样音量<input id="sampler-gain" type="number" min="0.05" max="1.5" step="0.05" value="${draft?.gain??.8}" aria-label="采样音量"></label><label>${track.kind==='tonal'?'松开后余音':'鼓声最长时长'}（秒）<input id="sampler-release" type="number" min="0.02" max="2" step="0.02" value="${draft?.release??.2}" aria-label="采样余音或时长"></label><label>明亮程度（Hz）<input id="sampler-cutoff" type="number" min="200" max="18000" step="100" value="${draft?.cutoff??18000}" aria-label="采样低通截止"></label></div><div class="sound-actions"><button id="sampler-preview" class="quiet compact">${isQuiet()?'静音检查':'试听草稿'}</button></div><p class="sampler-help">应用前会读取并校验随包素材，再保存备份；失败不会自动换回合成。旧合成参数保留，只有切回合成时才发声。This window never previews automatically.</p><details><summary>采样来源与边界</summary><p>VSCO 2 Community Edition · CC0。Versilian Studios / Sam Gossner、Ivy Audio / Simon Dalzell；原始采样切分 Elan Hickler / Soundemote。<a href="https://github.com/sgossner/VSCO-2-CE" target="_blank" rel="noreferrer">原始资料</a>。架子鼓素材来自 menegass / Freesound，经 Sonic Pi 与 samblenny 的 CC0 素材集合；<a href="https://github.com/samblenny/web-midi-drumkit/blob/main/LICENSES/LICENSE_SAMPLES.md" target="_blank" rel="noreferrer">鼓素材许可</a>. Guitar: D. Smolken / Karoryfer Shinyguitar, CC0; microphone recordings only, four dynamics and two alternate takes. <a href="https://github.com/sfzinstruments/karoryfer.shinyguitar" target="_blank" rel="noreferrer">Guitar source and license</a>. FluidR3 GM by Frank Wen is MIT-licensed; its original notice is bundled. <a href="https://github.com/pianobooster/fluid-soundfont" target="_blank" rel="noreferrer">Soundbank source</a>. Original Sprout EDM PCM is CC0 synthesis, not sampled acoustic instruments or branded hardware.</p><p>随包 44.1 kHz / 16-bit 单声道，旋律素材最长 6 秒，鼓最长 3 秒；去掉前置近静音并淡出末尾。Flute, cello, violin, clarinet and selected held SoundFont/EDM voices use sustain loops. One-shots and drums do not loop. Electronic sources are labeled synthesized or SoundFont, not acoustic recordings.无踏板共鸣，不是完整 SFZ / VST。工程只保存内置采样编号与参数；MIDI 不携带采样文件，WAV 使用实际采样。</p></details><div id="sampler-error" class="export-progress" role="status"></div></div>`,'<button class="quiet" data-close>取消</button><button id="sampler-apply" class="accent">加载、备份并应用到此轨</button>');
  const form=$('.sampler-form'),current=()=>ticket===serial&&form===$('.sampler-form')&&$('#modal').open,guard=()=>{if(!current()||at!==getRevision()||getSelected()!==trackId)throw Error('工程或选择已改变，请重新打开采样窗口。')};
  const settings=()=>{if(!draft)return undefined;return normalizeSampler(track.instrument,{preset:draft.preset,gain:+$('#sampler-gain').value,release:+$('#sampler-release').value,cutoff:+$('#sampler-cutoff').value})};
  const plan=()=>{guard();return setTrackSampler(getProject(),trackId,settings())};
  const error=e=>{if(current())$('#sampler-error').textContent=e.message};
  const update=(clearError=true)=>{if(!current()||loading)return;try{const next=plan();$('#sampler-fields').hidden=!draft;$('#sampler-description').textContent=draft?samplePreset(draft.preset).description+' 录音根音 '+samplerInfo(draft.preset).range.map(noteName).join('–')+'，'+samplerInfo(draft.preset).files+' 个文件。'+(soundOriginLabel(draft.preset)+'. ')+' 素材在本机，不需要账户。':'合成音源不需要采样文件。切回后继续使用之前保存的合成音色参数。';if(clearError!==false)$('#sampler-error').textContent='';$('#sampler-apply').disabled=JSON.stringify(next.tracks.find(t=>t.id===trackId).sampler)===JSON.stringify(track.sampler)}catch(e){error(e);$('#sampler-apply').disabled=true}};
  $('#sampler-preset').onchange=e=>{draft=e.target.value?normalizeSampler(track.instrument,{preset:e.target.value}):null;if(draft){$('#sampler-gain').value=draft.gain;$('#sampler-release').value=draft.release;$('#sampler-cutoff').value=draft.cutoff}update()};
  for(const input of form.querySelectorAll('input'))input.oninput=update;
  $('#sampler-preview').onclick=async()=>{try{const next=plan(),t=next.tracks.find(t=>t.id===trackId);if(isQuiet())return toast('草稿已校验，静音模式没有创建实时音频。');const snapshot=JSON.stringify(t.sampler),allowed=()=>{try{guard();return JSON.stringify(settings())===snapshot}catch{return false}};const played=await preview(t,allowed);if(!allowed()||played===false)return;toast('只试听草稿，没有应用到工程。')}catch(e){error(e)}};
  $('#sampler-apply').onclick=async()=>{
   if(loading)return;try{const next=plan(),config=next.tracks.find(t=>t.id===trackId).sampler;loading=true;$('#sampler-apply').disabled=true;for(const el of form.querySelectorAll('input,select,button'))el.disabled=true;$('#sampler-error').textContent=config?'正在读取与校验本机采样…':'正在备份并切回合成…';
    if(config)await library.loadPreset(config.preset);guard();
    await protectedChange(({fallback=false}={})=>{if(fallback){if(ticket!==serial||at!==getRevision()||getSelected()!==trackId)return}else{if(!current())return;guard()}if(commit(next)){$('#modal').close();toast(config?'采样音源已应用，音符与共享关系保持；可一次撤销。':'已切回合成，原合成参数保留；可撤销。')}},'切换声音来源前 · '+track.name);
   }catch(e){error(e)}finally{loading=false;if(current()){for(const el of form.querySelectorAll('input,select,button'))el.disabled=false;update(false)}}
  };update();
 };
}

export function createSamplerPaletteUI({getProject,getRevision,commit,protectedChange,modal,toast,library=sampleLibrary}){
 let serial=0;
 return function showSamplerPalette(){
  let plan;try{plan=planSamplerPalette(getProject())}catch(e){return toast(e.message)}
  const at=getRevision(),ticket=++serial;let loading=false;
  modal('Use recorded instruments',`<div class="sampler-palette-form"><p>Only tracks using the original built-in synth receive an acoustic recording. Existing sampled instruments, including EDM patches, and their settings stay unchanged. Notes, mix and shared Patterns stay intact.</p><div class="sampler-palette-list">${plan.changes.map(t=>`<div><strong>${escape(t.name)}</strong><span>${escape(t.label)}</span><small>${t.notes} 音符保持</small></div>`).join('')||'<p>Every track already uses a sampled source; nothing needs changing.</p>'}</div><p>Load and verify bundled recordings, save a backup, then apply once. One Undo restores the previous sources. Saved synth settings remain available. Choose guitar, violin or clarinet individually in Source; this action never replaces an existing sampled voice. No automatic playback or model call.</p><div id="sample-palette-error" role="status"></div></div>`,'<button class="quiet" data-close>取消</button><button id="sample-palette-apply" class="accent">加载、备份并替换 '+plan.changes.length+' 轨音色</button>');
  const root=$('.sampler-palette-form'),current=()=>ticket===serial&&root===$('.sampler-palette-form')&&$('#modal').open,guard=()=>{if(!current()||at!==getRevision())throw Error('工程或窗口已改变，请重新打开真实音色窗口。')};$('#sample-palette-apply').disabled=!plan.changes.length;
  $('#sample-palette-apply').onclick=async()=>{if(loading)return;try{guard();loading=true;$('#sample-palette-apply').disabled=true;for(const [index,id] of plan.presets.entries()){guard();$('#sample-palette-error').textContent='正在校验本机素材 '+(index+1)+' / '+plan.presets.length+' · '+samplePreset(id).name;await library.loadPreset(id)}guard();await protectedChange(({fallback=false}={})=>{if((!fallback&&!current())||ticket!==serial||at!==getRevision())return;if(commit(plan.project)){$('#modal').close();toast('已替换 '+plan.changes.length+' 轨真实音色，音符和混音保持；可一次撤销。')}},'整首替换真实音色前 · '+getProject().name)}catch(e){if(current())$('#sample-palette-error').textContent=e.message}finally{loading=false;if(current())$('#sample-palette-apply').disabled=!plan.changes.length||at!==getRevision()}};
 };
}
